{
  "title": "TB in Ethiopia: A Spreading Disease",
  "perWatchSecond": 1,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "An outbreak that will not stop",
      "goal": "See how the infectious population soars to nearly 12 million and stays high, showing TB persists when the reproduction number exceeds one.",
      "control": {
        "parameter": "beta",
        "label": "Contact rate",
        "lowEnd": "3.9e-7",
        "highEnd": "1.6e-6"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if people took twice as long to progress from latent to active TB?",
        "parameter": "gamma",
        "value": 0.113
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 10,
        "relation": "lower",
        "by": 4800000
      },
      "effect": "With progression halved, the infectious peak drops from 11.9 million to 7.1 million, lower by 4.8 million.",
      "prediction": {
        "prompt": "If people took twice as long to become infectious, what happens to the peak number of infectious people?",
        "claimed": "The peak will be lower",
        "other": "The peak will be higher"
      },
      "passage": {
        "title": "Abstract",
        "quote": "The results suggest that optimal conditions could lead to the elimination of TB."
      },
      "carryForward": "The infectious population peaks near 12 million and stays above 4 million for decades. The system is in a high-transmission regime where R0 exceeds one."
    },
    {
      "kind": "background",
      "finding": 1,
      "title": "A population that keeps growing",
      "goal": "See how a larger inflow of new people into the population sustains a higher level of active TB over decades.",
      "control": {
        "parameter": "lambda",
        "label": "Recruitment rate",
        "lowEnd": "829000",
        "highEnd": "3316000"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if twice as many people entered the population each year?",
        "parameter": "lambda",
        "value": 3316000
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 38,
        "time": 38,
        "relation": "higher",
        "by": 3000000
      },
      "effect": "With recruitment doubled, the infectious count at year 38 rises from 4.2 million to 7.3 million, higher by 3.1 million.",
      "prediction": {
        "prompt": "If twice as many people entered the population each year, what happens to the infectious count at year 38?",
        "claimed": "It will be higher",
        "other": "It will be lower"
      },
      "passage": {
        "title": "Results",
        "quote": "We obtained $R_0 = 2.67$ for the estimated model parameters, which are greater than one, indicating that the tuberculosis is continuously multiplying."
      },
      "carryForward": "With R0 at 2.67, TB is actively multiplying. More people entering the system means more cases persisting over time."
    },
    {
      {
        "kind": "idea",
        "finding": 2,
        "title": "Treatment pulls the curve down",
        "goal": "See how a faster treatment rate reduces the peak of active infections, moving the system toward eventual elimination.",
        "control": {
          "parameter": "delta",
          "label": "Treatment rate",
          "lowEnd": "0.34",
          "highEnd": "1.34"
        },
        "watch": "i",
        "whatIf": {
          "prompt": "What if the treatment rate for infectious individuals were doubled?",
          "parameter": "delta",
          "value": 1.34
        },
        "difference": {
          "compartment": "i",
          "summary": "peak",
          "at": null,
          "time": 10,
          "relation": "lower",
          "by": 4500000
        },
        "effect": "With the treatment rate doubled, the infectious peak drops from 11.9 million to 7.4 million, lower by 4.5 million.",
        "prediction": {
          "prompt": "If the treatment rate were doubled, what happens to the peak number of infectious people?",
          "claimed": "The peak will be lower",
          "other": "The peak will be higher"
        },
        "passage": {
          "title": "Discussion",
          "quote": "The result revealed that the infectious population decreases as the treatment rate of infected individuals increases; in the long run, this may lead to the eradication of the disease from the community."
        },
        "carryForward": "Faster treatment is one of the most effective levers for reducing the infectious population and moving toward elimination."
      }
    },
    {
      "kind": "method",
      "finding": 3,
      "title": "How fast people become infectious",
      "goal": "See how the speed of progression from latent to active TB drives the size of the outbreak peak.",
      "control": {
        "parameter": "gamma",
        "label": "Progression rate",
        "lowEnd": "0.11",
        "highEnd": "0.45"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if people progressed from latent to active TB twice as fast?",
        "parameter": "gamma",
        "value": 0.45
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 10,
        "relation": "higher",
        "by": 7200000
      },
      "effect": "With progression doubled, the infectious peak rises from 11.9 million to 19.2 million, higher by 7.3 million.",
      "prediction": {
        "prompt": "If people progressed from latent to active TB twice as fast, what happens to the peak number of infectious people?",
        "claimed": "The peak will be higher",
        "other": "The peak will be lower"
      },
      "passage": {
        "title": "Sensitivity Analysis",
        "quote": "rate of progression from the exposed class to the infectious class ($gamma$) were the most important factors."
      },
      "carryForward": "Progression rate is one of the top drivers of TB transmission. Faster progression means a much larger outbreak peak."
    },
    {
      "kind": "result",
      "finding": 4,
      "title": "Death as a brake on spread",
      "goal": "See how a higher disease death rate among the infectious reduces the peak of active infections.",
      "control": {
        "parameter": "tau",
        "label": "Disease death rate",
        "lowEnd": "0.13",
        "highEnd": "0.53"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if the disease death rate among infectious people were doubled?",
        "parameter": "tau",
        "value": 0.532
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 10,
        "relation": "lower",
        "by": 2300000
      },
      "effect": "With the disease death rate doubled, the infectious peak drops from 11.9 million to 9.6 million, lower by 2.3 million.",
      "prediction": {
        "prompt": "If the disease death rate were doubled, what happens to the peak number of infectious people?",
        "claimed": "The peak will be lower",
        "other": "The peak will be higher"
      },
      "passage": {
        "title": "Sensitivity Analysis",
        "quote": "Parameters with negative sensitivity indices ($mu$, $pi$, $delta$, $tau$) have the effect of lowering the community's TB burden if their values increases"
      },
      "carryForward": "Parameters with negative sensitivity indices, including disease death rate, lower the TB burden when increased. Together with treatment and vaccination, they form the main levers for control."
    }
  ],
  "limits": [
    "The model runs in years; one real second of watching equals one model year at normal speed.",
    "All compartments are head counts, not fractions; the total population is roughly 92 million.",
    "The control slider sets a rate parameter; the What-if world changes exactly one value and runs beside the base world.",
    "A prediction is scored before the What-if world runs; the learner commits to higher or lower first.",
    "The measured difference must be visible on the chart: the two curves must part by at least one tenth of the chart height."
  ]
}
